use verus::prelude::*;

verus! {

    /// Returns true iff every element of `v` is identical.
    /// By convention, empty and singleton slices are considered "all equal."
    ///
    /// Specification:
    ///   result == (forall i, j. i < v.len() && j < v.len() ==> v[i] == v[j])
    pub fn mall_equal1(v: &[i32]) -> bool
        ensures
            result
            == (forall|i: usize, j: usize|
                  i < v.len() && j < v.len() ==> v[i] == v[j])
    {
        let n = v.len();

        // Empty or singleton slices are trivially all‐equal.
        if n <= 1 {
            return true;
        }

        // Remember the first element; we will compare all others to it.
        let first = v[0];

        // `ok` means "so far, all seen elements equal `first`."
        let mut ok: bool = true;
        let mut i: usize = 1;

        // Loop invariant tracks two facts:
        //  1) If ok==true, then for all k < i, v[k] == first.
        //  2) If ok==false, then there exists some k < i with v[k] != first.
        while i < n
            invariant i <= n
            invariant ok ==> forall|k: usize| k < i ==> v[k] == first
            invariant !ok ==> exists|k: usize| k < i && v[k] != first
            decreases n - i
        {
            if ok && v[i] != first {
                ok = false;
            }
            i += 1;
        }

        // At this point:
        //   - if ok==true, we've seen v[k]==first for all k<n, hence all pairs equal
        //   - if ok==false, there is some k<n with v[k]!=first, hence not all equal
        ok
    }

}